'use strict';

function createChoiceModel(options) {
  if (!Array.isArray(options) || options.length === 0 ||
      options.some((value) => typeof value !== 'string' || value.length === 0) ||
      new Set(options).size !== options.length) {
    throw new TypeError('options must be distinct nonempty strings');
  }

  const allowed = options.slice();
  let selected = null;

  return {
    select(value) {
      if (!allowed.indexOf(value)) {
        selected = value;
        return true;
      }
      return false;
    },
    current() {
      return selected;
    },
    message() {
      return selected === null ? 'Nothing chosen' : `Chosen: ${selected}`;
    }
  };
}

module.exports = { createChoiceModel };

