'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['createChoiceModel']);
const { createChoiceModel } = api;

const options = ['red', 'green', 'blue'];
const model = createChoiceModel(options);
assert.equal(model.current(), null);
assert.equal(model.message(), 'Nothing chosen');
options[0] = 'changed';
options.push('yellow');
assert.equal(model.select('changed'), false);
assert.equal(model.current(), null);
assert.equal(model.select('red'), true);
assert.equal(model.current(), 'red');
assert.equal(model.message(), 'Chosen: red');
assert.equal(model.select('RED'), false);
assert.equal(model.select(0), false);
assert.equal(model.select('yellow'), false);
assert.equal(model.current(), 'red');
assert.equal(model.message(), 'Chosen: red');
assert.equal(model.select('blue'), true);
assert.equal(model.current(), 'blue');
assert.equal(model.message(), 'Chosen: blue');

const whitespace = createChoiceModel([' ']);
assert.equal(whitespace.select(' '), true);
assert.equal(whitespace.message(), 'Chosen: ' + ' ');

for (const invalid of [
  null, {}, 'red', [], [''], ['a', 'a'], ['a', 2], ['a', null]
]) {
  assert.throws(() => createChoiceModel(invalid), TypeError);
}

